function makeBrief(ms){let prefix=dataset.meta.data_kind==='example'?'[가상 데이터 예시] ':'';let lines=[`${prefix}[커버리지 수급 모니터링] 브리핑 ${dataset.meta.as_of||'데이터 미연결'}`,`출처: ${dataset.meta.source} / ${dataset.meta.status} / ${ms.length}종목`, ''];let groups=[['A','① 연기금 신규 매집',m=>`5일 ${num(m.actors.pension[5].amount,1)}억 · 20일 ${num(m.actors.pension[20].amount,1)}억 / 직전 20일 순매도 → 최근 5일 순매수 · 최근5일 매수 ${m.rows.slice(-5).filter(r=>r.pension>0).length}일`],['D','② 외국인 매수 가속',m=>`5일 ${num(m.actors.foreign[5].amount,1)}억 / 직전 15일 대비 일평균 ${num(m.actors.foreign.acceleration,1)}억 증가`],['B','③ 외국인·연기금 동반 매집',m=>`양측 5·20일 순매수 / 일별 동반 순매수 ${m.together}일 연속`],['E','④ 수급 이탈 경고',m=>`최근 5일 연기금 ${num(m.actors.pension[5].amount,1)}억 · 외국인 ${num(m.actors.foreign[5].amount,1)}억 / 최근 매도 전환 또는 동반 매도`],['C','⑤ 주가·수급 괴리',m=>`상대수익률 ${percent(m.rel20)} / 20일 연기금 ${num(m.actors.pension[20].amount,1)}억 · 외국인 ${num(m.actors.foreign[20].amount,1)}억`]];for(let [k,title,fn]of groups){lines.push(title);let a=ms.filter(m=>m.signals.includes(k));lines.push(...(a.length?a.map(m=>`· ${m.last.name}: ${fn(m)}`):[dataset.rows.length?'· 기준 충족 종목 없음':'· 데이터 미연결']),'');}lines.push('⑥ 패시브 수급 영향');let ev=ms.flatMap(m=>m.events.map(e=>`· ${m.last.name} ${e.date}: ${e.type} / ${e.source_url}`));lines.push(...(ev.length?ev:['· 미확인 — 검증된 ETF·지수·대량거래 이벤트가 없습니다.']),'','오늘의 추가 분석 우선순위');let top=ms.filter(m=>m.signals.length&&finite(m.score)).sort((a,b)=>b.score-a.score).slice(0,3);lines.push(...(top.length?top.map(m=>`· ${m.last.name}: ${m.signals.map(k=>SIGNALS[k]).join(', ')} / 탐색 점수 ${m.score.toFixed(1)}점`):['· 선정 보류 — 유효 신호·점수 데이터 부족']),'','신호는 추가 분석 대상이며 저평가·향후 상승을 확정하지 않습니다.');return lines.join('\n')}
function download(name,text,type='text/plain'){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function openSettings(){for(let k of Object.keys(DEFAULTS))$(k).value=settings[k];$('weights').innerHTML=['연기금20일','외국인20일','수급 가속도','매수 지속성','가격·수급 괴리'].map((name,i)=>`<label>${name}<input id="weight${i}" type="number" min="0" value="${weights[i]}"></label>`).join('');$('settingsError').textContent='';$('settings').showModal()}
$('settingsBtn').onclick=openSettings;$('resetSettings').onclick=()=>{settings={...DEFAULTS};weights=[30,25,20,15,10];$('settings').close();openSettings()};$('saveSettings').onclick=()=>{let next=Object.fromEntries(Object.keys(DEFAULTS).map(k=>[k,Number($(k).value)])),ws=weights.map((w,i)=>Number($('weight'+i).value));if(Object.values(next).some(v=>!finite(v)||v<0)||next.minBuyDays<1||next.minBuyDays>5||!Number.isInteger(next.minBuyDays)||next.passiveVolume<1||ws.some(v=>!finite(v)||v<0)||!ws.some(v=>v>0)){$('settingsError').textContent='임계값과 가중치를 확인하세요. 매수 일수는 1~5의 정수, 거래량 배수는 1 이상입니다.';return}settings=next;weights=ws;try{localStorage.setItem('gs-flow-settings-v2',JSON.stringify({settings,weights}))}catch{}$('settings').close();recalc()};
$('cards').onclick=e=>{let el=e.target.closest('[data-signal]');if(el){signal=signal===el.dataset.signal?null:el.dataset.signal;render()}};$('clearFilter').onclick=()=>{signal=null;render()};function selectRow(e){let row=e.target.closest('[data-code]');if(row){selected=row.dataset.code;render()}}$('rows').onclick=selectRow;$('rows').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectRow(e)}};function setSort(e){let h=e.target.closest('[data-sort]');if(h){sort={key:h.dataset.sort,desc:sort.key===h.dataset.sort?!sort.desc:true};render()}}$('head').onclick=setSort;$('head').onkeydown=e=>{if(e.key==='Enter')setSort(e)};document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{$('period').value=b.dataset.period;renderDetail(visible().find(m=>m.last.code===selected));});for(let id of ['sector','search'])$(id).oninput=render;$('benchmark').onchange=recalc;for(let id of ['period','metricPeriod'])$(id).onchange=()=>renderDetail(visible().find(m=>m.last.code===selected));window.addEventListener('resize',()=>charts.forEach(c=>c.resize()));
