$('file').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let text=await f.text(),obj;if(f.name.toLowerCase().endsWith('.json'))obj=JSON.parse(text);else{if(!$('csvSource').value.trim())throw Error('CSV 출처를 입력하세요.');let rows=parseCSV(text),dates=[...new Set(rows.map(r=>r.date))].sort();obj={schema_version:2,meta:{data_kind:$('csvKind').value,source:$('csvSource').value.trim(),unit:'KRW_100M',benchmark_name:'KOSPI (사용자 제공)',price_basis:$('csvBasis').value,adjustment_as_of:null,dividend_adjusted:$('csvDividend').value==='unknown'?null:$('csvDividend').value==='true',status:$('csvState').value,fetched_at:new Date().toISOString(),as_of:dates.at(-1),trading_dates:dates,csv_calendar_inferred:true,notes:['사용자가 제공한 CSV입니다. 원자료의 정확성과 이용권한은 별도 확인이 필요합니다.']},rows};}let next=validateDataset(obj);if(!next.rows.length)throw Error('파일에 관측 데이터가 없습니다.');dataset=next;signal=null;selected=null;$('sector').value='전체 업종';$('search').value='';$('import').close();recalc()}catch(err){$('importError').textContent=err.message}e.target.value=''};
$('exportBtn').onclick=()=>{const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';let rows=visible().map(m=>columns.map(([k])=>k==='signals'?m.signals.map(s=>SIGNALS[s]).join(' / '):k==='spark'?'':value(m,k)));download('coverage_flow_screen.csv','\ufeff'+[columns.map(c=>c[1]),...rows].map(r=>r.map(quote).join(',')).join('\n'),'text/csv;charset=utf-8')};$('copyBrief').onclick=async()=>{try{await navigator.clipboard.writeText(brief);$('copyBrief').textContent='복사 완료';setTimeout(()=>$('copyBrief').textContent='브리핑 복사',1500)}catch{$('copyBrief').textContent='복사 실패 — 본문을 선택해 복사하세요'}};
$('sourceBtn').onclick=()=>{let m=dataset?.meta||{};let entries=[['데이터 구분',m.data_kind],['원천',m.source],['기준일',m.as_of||'미연결'],['갱신시각',fmtDate(m.fetched_at)],['잠정/확정',m.status],['금액 단위','억원 (KRW_100M), 수량은 주'],['가격 기준',m.price_basis+' / 수정 기준 '+(m.adjustment_as_of||'미확인')],['배당 반영',m.dividend_adjusted===null?'미확인':m.dividend_adjusted?'반영':'미반영'],['벤치마크',m.benchmark_name],['커버리지',`${items.length}개 관측 / 설정 ${coverage.length}종목. 설정된 커버리지 기준; 전 종목 수집은 별도 확장 필요.`],['최근 수집',status?.message||'실행 기록 없음']];$('sourceContent').innerHTML=`<table class="source-table">${entries.map(([k,v])=>`<tr><td>${escape(k)}</td><td>${escape(v)}</td></tr>`).join('')}</table><h3 style="margin-top:20px">산식과 누락 처리</h3><ul><li>상대수익률 = (종목 현재/기준일 주가) ÷ (벤치마크 현재/기준일 지수) − 1. 20일 수익률에는 21개 종가가 필요합니다. %로 표시합니다.</li><li>시총 대비 = 기간 순매수 ÷ 최종일 시총. 거래대금 대비 = 기간 순매수 ÷ 동일 기간 거래대금 합계. 각각 독립적으로 계산합니다.</li><li>가속도 = 최근 5일 일평균 − 직전 15일 일평균. 표의 가속도는 외국인·연기금 합계입니다.</li><li>A: 직전20일(최근5일 제외) 매도 → 최근5일 순매수, 최소 매수일수 적용. B: 양측 5·20일 양수. D: 외국인 5일 양수와 가속도 임계값 충족.</li><li>E: 직전20일 양수→최근5일 음수 또는 양측5일 순매도. F: 확인된 관련 이벤트와 거래량 배수 조건을 모두 충족할 때만 의심 표시. 패시브 매매금액을 차감하지 않습니다.</li><li>외국인 신규 매집은 A를 외국인에 동일하게 적용합니다. 동반 매집 지속 기간은 일별 양측 순매수 연속일수입니다.</li><li>선택기간 차트는 첫날을 0으로 두고 다음 날부터 합산합니다. 기간 누적 표는 선택된 모든 거래일을 합산하므로 첫날 금액만큼 차이가 납니다.</li><li>데이터가 없거나 필요한 거래일이 부족하면 —를 표시합니다. 투자주체 값이 누락된 기간은 합계·신호를 계산하지 않습니다. 거래대금 0의 비율은 계산하지 않습니다.</li><li>차트 3M·6M·1Y는 최종 관측일 기준 달력 기간입니다. YTD는 전년 마지막 관측 종가가 기준이며, 데이터가 부족하면 확보 구간만 표시합니다. 기간 선택은 차트에 적용되며 표·시그널의 5·20·60거래일 계산은 유지됩니다.</li><li>국민연금 공시 지분율은 전체 연기금 지분율과 다릅니다. 보유 기준일과 공시일을 구분하며 순매수로 현재 지분율을 추정하지 않습니다.</li><li>외국인 보유비율은 보유주식수/상장주식수입니다. 한도소진율을 대신 사용하지 않습니다. 보유비율 변화는 %p입니다.</li><li>탐색 점수: 전체 데이터 커버리지에서 표준화(±3 제한)한 5개 지표를 가중합. 최소 3종목, 필수값 완비 시에만 0~100으로 표시합니다. 정확한 가중치는 탐지 기준에서 변경할 수 있습니다.</li></ul><h3>데이터 확보 제약</h3><p>KRX 공식 Open API는 인증키·서비스 승인이 필요합니다. 공개 목록에서 세부 투자자별 수급 API는 확인되지 않았습니다. pykrx는 비공식 수집 도구이며 인증·공급자 이용조건을 확인해야 합니다. 수집 실패 시 예시 데이터로 대체하지 않습니다.</p><p>CSV는 파일 내 날짜에서 거래일을 추론하므로 전체 누락일 검출에 한계가 있습니다. 운영 JSON에는 공급자의 거래일 목록을 포함하세요. 새로고침하면 업로드 파일은 유지되지 않습니다.</p><p><a href="https://openapi.krx.co.kr/contents/OPP/INFO/OPPINFO003.jsp" target="_blank" rel="noopener noreferrer">KRX 이용방법</a> · <a href="https://github.com/sharebook-kr/pykrx" target="_blank" rel="noopener noreferrer">pykrx 문서</a></p><p>${escape((m.notes||[]).join(' / '))}</p>`;$('sources').showModal()};$('closeSources').onclick=()=>$('sources').close();
async function load(url){let r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);dataset=validateDataset(await r.json());}
async function start(){try{let rs=await Promise.allSettled([fetch('data/coverage.json').then(r=>r.json()),fetch('data/status.json',{cache:'no-store'}).then(r=>r.json()),fetch('data/pension-holdings.json',{cache:'no-store'}).then(r=>r.json())]);if(rs[0].status==='fulfilled')coverage=rs[0].value;if(rs[1].status==='fulfilled')status=rs[1].value;if(rs[2].status==='fulfilled'&&Array.isArray(rs[2].value.records))pensionHoldings=rs[2].value;await load('data/market.json');recalc()}catch(e){$('notice').textContent='데이터 로드/검증 실패: '+e.message;$('mode').textContent='데이터 오류';$('empty').hidden=false;}}
start();
